def digest(data):
    return hashlib.sha256(data).hexdigest()


def root_dir():
    # When placed at ~/IPTH_Traceability/Interplex_MES_FE and invoked from BE.
    fe = pathlib.Path(__file__).resolve().parent
    if fe.name != 'Interplex_MES_FE':
        raise RuntimeError('REJECT: place this updater at Interplex_MES_FE repository root.')
    root = fe.parent
    if not (root / 'Interplex_MES_BE' / 'app' / 'api' / 'v1' / 'api.py').is_file():
        raise RuntimeError('REJECT: expected neighboring Interplex_MES_BE not found.')
    return root


def current_hash(path):
    return digest(path.read_bytes()) if path.is_file() else None


def backup_dir():
    return pathlib.Path.home() / '.ipth_mes_updater_backups' / VERSION


def check(root):
    failures=[]; before=0; after=0; state=[]
    for d in DEPENDENCIES:
        actual=current_hash(root/d['path'])
        if actual == d['sha256']: print('[PASS] dependency', d['path'])
        else:
            failures.append('DEPENDENCY ' + d['path'])
            print('[REJECT] dependency', d['path'], 'actual=', actual, 'required=', d['sha256'])
    for item in MANIFEST:
        actual=current_hash(root/item['path'])
        if actual==item['before']:
            before+=1; state.append('before'); print('[BEFORE]', item['path'])
        elif actual==item['after']:
            after+=1; state.append('after'); print('[AFTER]', item['path'])
        else:
            failures.append('SOURCE ' + item['path'])
            print('[REJECT] unexpected source', item['path'], 'actual=', actual,
                  'expected_before=', item['before'], 'expected_after=', item['after'])
    if failures:
        return 'REJECT', failures
    if before and after:
        print('[REJECT] mixed installation state; no partial overwrite allowed.')
        return 'REJECT', ['MIXED_INSTALLATION']
    return ('ALREADY_APPLIED' if after else 'PASS'), []


def atomic_write(path, data):
    path.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=path.parent, prefix='.ipth-tmp-', delete=False) as file:
        temp=pathlib.Path(file.name)
        file.write(data); file.flush(); os.fsync(file.fileno())
    try: os.replace(temp,path)
    finally: temp.unlink(missing_ok=True)


def decoded(item):
    data=zlib.decompress(base64.b64decode(PAYLOADS[item['path']]))
    if digest(data) != item['after']: raise RuntimeError('Embedded bundle checksum mismatch: '+item['path'])
    return data


def apply(root):
    state, fail=check(root)
    if state=='ALREADY_APPLIED':
        print('VERDICT: ALREADY_APPLIED — no-op'); return
    if state!='PASS': raise RuntimeError('VERDICT: REJECT — '+str(fail))
    backup=backup_dir()
    if backup.exists():
        raise RuntimeError('REJECT: backup directory already exists, manual inspection required: '+str(backup))
    backup.mkdir(parents=True)
    previous=[]
    try:
        for item in MANIFEST:
            target=root/item['path']
            data=target.read_bytes() if target.is_file() else None
            previous.append((target,data))
            if data is not None:
                stored=backup/item['path']
                stored.parent.mkdir(parents=True,exist_ok=True)
                stored.write_bytes(data)
        (backup/'manifest.json').write_text(json.dumps(MANIFEST,indent=2),encoding='utf-8')
        for item in MANIFEST:
            target=root/item['path']
            atomic_write(target,decoded(item))
            if current_hash(target)!=item['after']:
                raise RuntimeError('VERIFY WRITE FAILED: '+item['path'])
            print('[APPLIED]',item['path'])
    except Exception:
        for target,data in reversed(previous):
            try:
                if data is None: target.unlink(missing_ok=True)
                else: atomic_write(target,data)
            except OSError as recovery_error: print('[CRITICAL] recovery error:',recovery_error)
        shutil.rmtree(backup,ignore_errors=True)
        raise
    print('APPLIED: SOURCE/DOC/SQL FILES ONLY. NO DATABASE EXECUTION.')
    print('BACKUP:',backup)
    print('NEXT: manual V0003 PRECHECK > APPLY > VERIFY before restarting BE.')


def rollback(root):
    backup=backup_dir()
    if not backup.is_dir(): raise RuntimeError('REJECT: backup not found: '+str(backup))
    state,fail=check(root)
    if state!='ALREADY_APPLIED': raise RuntimeError('REJECT: rollback requires unchanged installed files: '+str(fail))
    stored=json.loads((backup/'manifest.json').read_text())
    if stored!=MANIFEST: raise RuntimeError('REJECT: saved manifest does not match version.')
    for item in MANIFEST:
        if item['before'] is not None:
            copy=backup/item['path']
            if current_hash(copy)!=item['before']:
                raise RuntimeError('REJECT: backup damaged: '+item['path'])
    for item in reversed(MANIFEST):
        target=root/item['path']
        if item['before'] is None: target.unlink(missing_ok=True)
        else: atomic_write(target,(backup/item['path']).read_bytes())
        if current_hash(target)!=item['before']:
            raise RuntimeError('ROLLBACK VERIFY FAILED: '+item['path'])
        print('[RESTORED]',item['path'])
    print('ROLLBACK COMPLETED: code/docs/SQL files only; DB schema/data unchanged.')


def main():
    p=argparse.ArgumentParser(description=__doc__)
    group=p.add_mutually_exclusive_group(required=True)
    group.add_argument('--scan',action='store_true')
    group.add_argument('--apply',action='store_true')
    group.add_argument('--rollback',action='store_true')
    args=p.parse_args()
    root=root_dir()
    print('=== MES2 UTILITIES V1 — SOURCE & DOC UPDATER ===')
    print('ROOT:',root)
    print('No database access in this updater. Manual V0003 SQL required.')
    if args.scan:
        verdict,issues=check(root)
        print('VERDICT:',verdict, ('— ready to APPLY files only' if verdict=='PASS' else ''))
        if issues: sys.exit(2)
    elif args.apply: apply(root)
    else: rollback(root)

if __name__=='__main__':
    try: main()
    except Exception as e:
        print('VERDICT: REJECT / ERROR:',e,file=sys.stderr)
        sys.exit(2)
